def roman_to_int(s):
    values = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    for i in range(len(s)):
        if i + 1 < len(s) and values[s[i]] < values[s[i+1]]:
            total -= values[s[i]]
        else:
            total += values[s[i]]
    return total

def flatten(nested):
    result = []
    for item in nested:
        if isinstance(item, list):
            result.extend(flatten(item))
        else:
            result.append(item)
    return result

def rotate_matrix(m):
    if not m:
        return []
    return [list(row) for row in zip(*m[::-1])]

def group_anagrams(words):
    d = {}
    for w in words:
        key = ''.join(sorted(w))
        d.setdefault(key, []).append(w)
    result = [sorted(g) for g in d.values()]
    result.sort(key=lambda g: g[0])
    return result

def longest_common_prefix(strs):
    if not strs:
        return ""
    prefix = strs[0]
    for s in strs[1:]:
        while not s.startswith(prefix):
            prefix = prefix[:-1]
            if not prefix:
                return ""
    return prefix

def is_valid_ipv4(s):
    if not isinstance(s, str):
        return False
    parts = s.split('.')
    if len(parts) != 4:
        return False
    for part in parts:
        if len(part) == 0 or len(part) > 3:
            return False
        if not all('0' <= c <= '9' for c in part):
            return False
        if len(part) > 1 and part[0] == '0':
            return False
        if not 0 <= int(part) <= 255:
            return False
    return True

def median(nums):
    """Return the median of a non-empty list of numbers."""
    s = sorted(nums)
    n = len(s)
    mid = n // 2
    if n % 2 == 1:
        return s[mid]
    else:
        return (s[mid - 1] + s[mid]) / 2

def chunk(items, size):
    """Split items into lists of length size. The last list may be shorter."""
    return [items[i:i + size] for i in range(0, len(items), size)]

def is_sorted(nums, reverse=False):
    """True if nums is sorted ascending (or descending if reverse=True).
    Equal neighbours are allowed."""
    for a, b in zip(nums, nums[1:]):
        if reverse:
            if a < b:
                return False
        else:
            if a > b:
                return False
    return True

def fib(n):
    """Return the n-th Fibonacci number, with fib(0) = 0 and fib(1) = 1."""
    if n < 2:
        return n
    a, b = 0, 1
    for _ in range(2, n + 1):
        a, b = b, a + b
    return b

def average(nums):
    """Return the mean of a list of numbers."""
    filtered = [n for n in nums if n is not None]
    if not filtered:
        return None
    return round(sum(filtered) / len(filtered), 2)
